# The old single allergen choices, as the new names
OLD = {"Eggs": "Egg", "Milk": "Dairy", "Mustard": "Mustard", "Peanuts": "Peanuts", "Fish": "Fish", "Sesame seeds": "Sesame",
       "Soy": "Soy", "Sulphites": "Sulphites", "Tree Nuts": "Tree nuts", "Wheat and triticale": "Gluten", "Crustaceans": "Shellfish"}


def copy_allergens(apps, schema_editor):
    Ingredient = apps.get_model("pos_server", "Ingredient")
    for ingredient in Ingredient.objects.exclude(allergen__isnull=True).exclude(allergen=""):
        new = OLD.get(ingredient.allergen)
        if new:
            ingredient.allergens = [new]
            ingredient.animal = new in ("Dairy", "Egg")
            ingredient.fish = new in ("Fish", "Shellfish")
            ingredient.save(update_fields=["allergens", "animal", "fish"])


